private Session OpenPeekWindow(string path) =>
    OpenPeekWindow(path, Key.Ctrl, Key.Space);

private Session OpenPeekWindow(string path, params Key[] chord)
{
    OpenExplorerAndSelect(path);
    return SendPeekHotkeyWithRetry(path, chord);
}

