{
    using var snapshot = SettingsConfigHelper.PreserveModuleSettings("Peek");
    try
    {
        ConfigurePeekActivation(useBareSpace: true);
        RestartRunnerForPeekSettings();
        // Alternate 8.png and 2.jpg; assert bounds change after every reopen.
    }
    finally
    {
        CloseTestWindows(preservePeekProcess: false);
        snapshot.Dispose();
        RestartRunnerForPeekSettings();
